```tsx
import React, { useState } from 'react';

interface Props {
    onUnlock: () => void;
}

type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

const CamouflageScreen: React.FC<Props> = ({ onUnlock }) => {
    const [sequence, setSequence] = useState<Direction[]>([]);
    const [showAuth, setShowAuth] = useState(false);
    const [code, setCode] = useState('');
    const [error, setError] = useState(false);

    // U U D D L R L R
    const TARGET_SEQUENCE: Direction[] = ['UP', 'UP', 'DOWN', 'DOWN', 'LEFT', 'RIGHT', 'LEFT', 'RIGHT'];

    const handlePointerDown = (e: React.PointerEvent) => {
        if (showAuth) return;

        // Visual feedback prevention for non-inputs
        if (e.target instanceof HTMLElement && e.target.tagName !== 'INPUT') {
             e.preventDefault();
        }

        const clientX = e.clientX;
        const clientY = e.clientY;

        const width = window.innerWidth;
        const height = window.innerHeight;
        const centerX = width / 2;
        const centerY = height / 2;

        const dx = clientX - centerX;
        const dy = clientY - centerY;

        let dir: Direction;

        // X-shape quadrant logic
        if (Math.abs(dx) > Math.abs(dy)) {
            dir = dx > 0 ? 'RIGHT' : 'LEFT';
        } else {
            dir = dy > 0 ? 'DOWN' : 'UP';
        }

        setSequence(prev => {
            const newSeq = [...prev, dir];
            if (newSeq.length > TARGET_SEQUENCE.length) {
                newSeq.shift();
            }

            const isMatch = newSeq.length === TARGET_SEQUENCE.length && 
                            newSeq.every((val, index) => val === TARGET_SEQUENCE[index]);

            if (isMatch) {
                setShowAuth(true);
            }

            return newSeq;
        });
    };

    const handleAuthSubmit = (e?: React.FormEvent) => {
        e?.preventDefault();
        if (code.toUpperCase() === 'BA') {
            onUnlock();
            setSequence([]);
            setShowAuth(false);
            setCode('');
        } else {
            setError(true);
            setCode('');
            setTimeout(() => setError(false), 1000);
        }
    };

    return (
        <div 
            className="fixed inset-0 z-[9999] bg-white text-[#151a25] font-sans flex flex-col cursor-default select-none touch-none overflow-y-auto"
            onPointerDown={handlePointerDown}
        >
            <div className="flex-1 flex flex-col items-start justify-center p-6 md:p-12 max-w-[600px] mx-auto w-full">
                {/* Main Content Card - No stopPropagation to allow gestures */}
                <div className="w-full pointer-events-auto">
                    <h1 className="text-[32px] md:text-[36px] font-bold leading-tight mb-6 tracking-tight text-[#222]">
                        Site not found
                    </h1>

                    <p className="text-[#4b5563] text-[17px] leading-relaxed mb-8">
                        Looks like you followed a broken link or entered a URL that doesn’t exist on Netlify.
                    </p>

                    <hr className="border-t border-gray-200 mb-8" />

                    <p className="text-[#4b5563] text-[17px] leading-relaxed mb-8">
                        If this is your site, and you weren’t expecting a 404 for this path, please visit Netlify’s <span className="text-[#00ad9f] cursor-pointer hover:underline">“page not found” support guide</span> for troubleshooting tips.
                    </p>

                    <div>
                        <p className="text-[#6b7280] text-sm mb-2">Netlify Internal ID:</p>
                        <div className="bg-[#f3f4f6] text-[#4b5563] font-mono text-[13px] p-3 rounded-md break-all inline-block">
                            01KBACCWKM5JZQCJ0Q8SP16VNX
                        </div>
                    </div>
                </div>
            </div>

            {/* Footer Logo */}
            <div className="p-8 flex items-center justify-center pointer-events-none">
                 <svg viewBox="0 0 50 50" className="w-10 h-10 opacity-50 grayscale" fill="currentColor">
                    <path d="M16.3 3.3c-1.3-.6-2.8-.2-3.7.9L1.4 17.6c-.8 1-1 2.2-.6 3.4l5.3 16.8c.4 1.3 1.5 2.2 2.9 2.4l17.2 2.7c1.4.2 2.8-.4 3.6-1.6L48.6 19c.8-1.1.7-2.6-.2-3.6L31.9 2.2c-1-1.1-2.6-1.4-4-.7L16.3 3.3z"/>
                 </svg>
            </div>

            {/* Auth Modal (Hidden Overlay) */}
            {showAuth && (
                <div 
                    className="absolute inset-0 bg-white/95 backdrop-blur-sm flex items-center justify-center z-50 cursor-auto"
                    onPointerDown={(e) => e.stopPropagation()} 
                >
                    <form onSubmit={handleAuthSubmit} className="bg-white shadow-2xl p-8 rounded-xl border border-gray-200 w-80 animate-fade-in">
                        <h3 className="text-lg font-bold mb-4 text-center text-gray-800">System Access</h3>
                        <input 
                            autoFocus
                            type="text" 
                            className={`w-full border-2 rounded-lg p-3 text-center text-xl tracking-widest uppercase outline-none transition-colors ${error ? 'border-red-500 bg-red-50' : 'border-gray-300 focus:border-[#00ad9f]'}`}
                            value={code}
                            onChange={e => setCode(e.target.value)}
                            placeholder="CODE"
                        />
                    </form>
                </div>
            )}
        </div>
    );
};

export default CamouflageScreen;

